interface.signature:
interface LengthPerformance {
  range: string; // "0-15s", "15-30s", etc.
  minSeconds: number;
  maxSeconds: number;
  videoCount: number;
  totalViews: number;
  avgEngagementRate: number;
  avgCompletionRate: number;
  topPerformer?: { contentId: string; views: number };
}

interface OptimalLengthRecommendation {
  format: 'reel' | 'video' | 'story';
  optimalRange: { min: number; max: number };
  sweetSpot: number;
  confidence: 'high' | 'medium' | 'low';
  basedOnVideos: number;
  avgEngagementInRange: number;
}
